def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    # Sort and remove duplicates
    sorted_nums = sorted(set(nums))

    result_parts = []
    n = len(sorted_nums)
    i = 0

    while i < n:
        start = i
        # Find the end of the current consecutive run
        while i + 1 < n and sorted_nums[i + 1] == sorted_nums[i] + 1:
            i += 1

        end = i
        run_length = end - start + 1

        # Collapse runs of 3 or more into "a..b"
        if run_length >= 3:
            result_parts.append(f"{sorted_nums[start]}..{sorted_nums[end]}")
        else:
            # Otherwise, list them individually
            for j in range(start, end + 1):
                result_parts.append(str(sorted_nums[j]))

        i += 1

    return ",".join(result_parts)
